-- Owner consent for source-only automation. No deployment permission.
CREATE TABLE mcp_sandbox_grants(client_id TEXT PRIMARY KEY REFERENCES mcp_clients(id) ON DELETE CASCADE,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,allow_delete INTEGER NOT NULL CHECK(allow_delete IN (0,1)),max_changes INTEGER NOT NULL CHECK(max_changes BETWEEN 1 AND 50),created_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE mcp_sandbox_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,client_id TEXT NOT NULL REFERENCES mcp_clients(id),token_id TEXT NOT NULL REFERENCES mcp_access_tokens(id),owner_id TEXT NOT NULL REFERENCES users(id),base_revision INTEGER NOT NULL,proposal_id TEXT REFERENCES proposals(id),status TEXT NOT NULL CHECK(status IN ('running','applied','failed')),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX mcp_sandbox_active_project ON mcp_sandbox_runs(project_id) WHERE status='running';
CREATE TRIGGER mcp_sandbox_approval_gate BEFORE UPDATE OF status ON proposals WHEN NEW.status='approved' AND EXISTS(SELECT 1 FROM mcp_sandbox_runs WHERE proposal_id=NEW.id) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mcp_sandbox_runs r JOIN mcp_sandbox_grants g ON g.client_id=r.client_id JOIN mcp_access_tokens t ON t.id=r.token_id JOIN mcp_clients c ON c.id=r.client_id JOIN memberships m ON m.user_id=r.owner_id JOIN projects p ON p.id=r.project_id AND p.workspace_id=m.workspace_id WHERE r.proposal_id=NEW.id AND r.status='running' AND r.base_revision=NEW.base_revision AND p.revision=NEW.base_revision AND m.role='owner' AND g.project_id=r.project_id AND g.owner_id=r.owner_id AND g.revoked_at IS NULL AND g.expires_at>NEW.decided_at AND r.expires_at>NEW.decided_at AND t.revoked_at IS NULL AND t.expires_at>NEW.decided_at AND c.revoked_at IS NULL AND NEW.approved_by=r.owner_id AND (g.allow_delete=1 OR NOT EXISTS(SELECT 1 FROM agent_patches a WHERE a.proposal_id=NEW.id AND a.destructive=1)) AND (SELECT json_array_length(a.changes_json) FROM agent_patches a WHERE a.proposal_id=NEW.id)<=g.max_changes) THEN RAISE(ABORT,'sandbox_authority_changed') END;
END;
ALTER TABLE mcp_sandbox_grants ADD COLUMN allow_publish INTEGER NOT NULL DEFAULT 0 CHECK(allow_publish IN (0,1));
ALTER TABLE mcp_sandbox_grants ADD COLUMN target_origin TEXT;
CREATE TABLE mcp_autopilot_deployments(job_id TEXT PRIMARY KEY REFERENCES ship_jobs(id) ON DELETE CASCADE,client_id TEXT NOT NULL REFERENCES mcp_clients(id),token_id TEXT NOT NULL REFERENCES mcp_access_tokens(id),owner_id TEXT NOT NULL REFERENCES users(id),target_origin TEXT NOT NULL);
CREATE TRIGGER mcp_autopilot_release_gate BEFORE INSERT ON ship_releases WHEN EXISTS(SELECT 1 FROM mcp_autopilot_deployments WHERE job_id=NEW.job_id) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mcp_autopilot_deployments d JOIN mcp_sandbox_grants g ON g.client_id=d.client_id JOIN mcp_access_tokens t ON t.id=d.token_id JOIN mcp_clients c ON c.id=d.client_id JOIN projects p ON p.id=g.project_id JOIN memberships m ON m.workspace_id=p.workspace_id AND m.user_id=d.owner_id WHERE d.job_id=NEW.job_id AND g.project_id=NEW.project_id AND g.owner_id=d.owner_id AND m.role='owner' AND g.revoked_at IS NULL AND g.expires_at>NEW.created_at AND g.allow_publish=1 AND g.target_origin=d.target_origin AND t.revoked_at IS NULL AND t.expires_at>NEW.created_at AND c.revoked_at IS NULL AND t.project_id=g.project_id AND t.user_id=d.owner_id AND t.client_id=d.client_id AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='release.publish') AND p.revision=NEW.version) THEN RAISE(ABORT,'autopilot_publish_authority_changed') END;
END;
